import React, { useEffect, useState } from 'react';
import api from '../../api';
import { toast } from 'react-toastify';

export default function OADesignations() {
  const [desigs, setDesigs] = useState([]);
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({ name: '', description: '' });
  const [editId, setEditId] = useState(null);

  const load = () => api.get('/designations').then(r => setDesigs(r.data));
  useEffect(() => { load(); }, []);

  const openAdd = () => { setForm({ name: '', description: '' }); setEditId(null); setShow(true); };
  const openEdit = d => { setForm({ name: d.name, description: d.description || '' }); setEditId(d._id); setShow(true); };

  const save = async e => {
    e.preventDefault();
    try {
      if (editId) await api.put(`/designations/${editId}`, form);
      else await api.post('/designations', form);
      toast.success('Saved'); setShow(false); load();
    } catch (err) { toast.error(err.response?.data?.message || 'Error'); }
  };

  return (
    <div>
      <div className="topbar">
        <h5 className="mb-0 fw-bold"><i className="bi bi-award me-2 text-primary"></i>Designations</h5>
        <button className="btn btn-primary btn-sm" onClick={openAdd}><i className="bi bi-plus-lg me-1"></i>Add Designation</button>
      </div>
      <div className="card">
        <div className="card-body p-0">
          <table className="table table-hover mb-0">
            <thead><tr><th>#</th><th>Name</th><th>Description</th><th>Actions</th></tr></thead>
            <tbody>
              {desigs.length === 0 && <tr><td colSpan={4} className="text-center text-muted py-4">No designations</td></tr>}
              {desigs.map((d, i) => (
                <tr key={d._id}><td>{i+1}</td><td className="fw-semibold">{d.name}</td><td>{d.description}</td>
                  <td><button className="btn btn-sm btn-outline-primary" onClick={() => openEdit(d)}><i className="bi bi-pencil"></i></button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      {show && (
        <div className="modal show d-block" style={{ background: 'rgba(0,0,0,0.5)' }}>
          <div className="modal-dialog"><div className="modal-content">
            <div className="modal-header" style={{ background: 'linear-gradient(135deg,#1a237e,#3949ab)', color: 'white' }}>
              <h5 className="modal-title">{editId ? 'Edit' : 'Add'} Designation</h5>
              <button className="btn-close btn-close-white" onClick={() => setShow(false)}></button>
            </div>
            <form onSubmit={save}>
              <div className="modal-body">
                <div className="mb-3"><label className="form-label fw-semibold">Name</label>
                  <input className="form-control" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required /></div>
                <div className="mb-3"><label className="form-label fw-semibold">Description</label>
                  <input className="form-control" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShow(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary">Save</button>
              </div>
            </form>
          </div></div>
        </div>
      )}
    </div>
  );
}
